before.max.go:
package numbers
func Max(xs []int) (int, bool) {
    best := xs[0]
    for _, x := range xs[1:] { if x > best { best = x } }
    return best, true
}

after.max.go:
package numbers
func Max(xs []int) (int, bool) {
    if len(xs) == 0 { return 0, false }
    best := xs[0]
    for _, x := range xs[1:] { if x > best { best = x } }
    return best, true
}

